export type {MotionEffect,MotionEffectMutation,EffectParameter,EffectParameterValue} from '@/components/nyc-tron/ui/components/forge/motion/motion-effects';
export interface EffectStackAndInspectorProps extends Omit<ViewProps,'children'> {
 readonly scope:string;readonly revision:string|number;readonly effects:readonly MotionEffect[];readonly selectedId:string|null;readonly onSelect:(id:string)=>void;
 readonly availableEffects:readonly {readonly id:string;readonly label:string}[];
 readonly onMutation:(mutation:MotionEffectMutation,signal:AbortSignal)=>void|Promise<void>;
 readonly height?:number;readonly disabled?:boolean;readonly unstyled?:boolean;
}
/** Host-controlled effect order and schema-driven settings. Processing and preset storage stay with the host. */
export function EffectStackAndInspector({scope,revision,effects,selectedId,onSelect,availableEffects,onMutation,height=320,disabled=false,unstyled=false,...props}:EffectStackAndInspectorProps){
 useMemo(()=>validateMotionEffects(effects),[effects]);useMemo(()=>validateEffectChoices(availableEffects),[availableEffects]);if(!scope.trim()||typeof revision==='number'&&!Number.isFinite(revision)||!Number.isFinite(height)||height<100||height>4000)throw new RangeError('Invalid effect stack scope or viewport');
 const [local,store]=useLocalStore(()=>({section:'stack',favorites:false}));const action=useOwnedAction(JSON.stringify([scope,revision])),locked=disabled||action.pending!==null,selected=effects.find(e=>e.id===selectedId);
 const run=(mutation:MotionEffectMutation)=>{if(!locked)void action.run(mutation.type,signal=>onMutation(mutation,signal));};
 const parameter=(parameterId:string,value:EffectParameterValue)=>{if(!selected||locked)return;const p=selected.parameters.find(p=>p.id===parameterId);if(!p)return;validateEffectParameterValue(p,value);run({type:'parameter',effectId:selected.id,parameterId,value});};
 return <View {...props} style={[{gap:space[2]},props.style]}>
  <SegmentedControl accessibilityLabel="Effect panel section" options={['stack','inspector','library'].map(value=>({value,label:value==='stack'?'Effect stack':value==='inspector'?'Effect inspector':'Effect library'}))} value={local.section} onChange={section=>store.set(s=>({...s,section}))} unstyled={unstyled}/>
  {local.section==='stack'?<><SettingSwitch label="Favorite effects only" on={local.favorites} onChange={favorites=>store.set(s=>({...s,favorites}))} disabled={disabled} styled={!unstyled}/>
   <FlatList data={local.favorites?effects.filter(e=>e.favorite):effects} keyExtractor={e=>e.id} style={{height}} initialNumToRender={6} windowSize={5} extraData={[locked,selectedId]} accessibilityLabel="Ordered effect stack" ListEmptyComponent={<Text {...{className:joinClasses(!unstyled&&'text-text-muted')}}>No matching effects</Text>}
    renderItem={({item})=>{const index=effects.indexOf(item);return <View style={{gap:space[1.5],padding:space[2]}}><Button title={item.label} accessibilityLabel={`Inspect ${item.label}`} disabled={disabled} unstyled={unstyled} onPress={()=>{if(!disabled){onSelect(item.id);store.set(s=>({...s,section:'inspector'}));}}}/>
     <Text {...{className:joinClasses(!unstyled&&'text-text-muted')}}>{`${index+1}. ${item.typeId}${item.bypassed?' · bypassed':''}`}</Text>
     <SettingSwitch label={`Bypass ${item.label}`} on={item.bypassed} disabled={locked} styled={!unstyled} onChange={value=>run({type:'bypass',effectId:item.id,value})}/>
     <SettingSwitch label={`Favorite ${item.label}`} on={item.favorite} disabled={locked} styled={!unstyled} onChange={value=>run({type:'favorite',effectId:item.id,value})}/>
     <View style={{flexDirection:'row',flexWrap:'wrap',gap:space[1.5]}}>{([-1,1] as const).map(direction=><Button key={direction} title={direction===-1?'Earlier':'Later'} accessibilityLabel={`Move ${item.label} ${direction===-1?'earlier':'later'}`} disabled={locked||index===(direction===-1?0:effects.length-1)} unstyled={unstyled} onPress={()=>run({type:'reorder',ids:moveMotionEffect(effects,item.id,direction)})}/>)}<Button title={`Remove ${item.label}`} disabled={locked} unstyled={unstyled} onPress={()=>run({type:'remove',effectId:item.id})}/></View>
    </View>;}}/></>:null}
  {local.section==='inspector'?<ScrollView style={{height}} contentContainerStyle={{gap:space[2]}} keyboardShouldPersistTaps="handled">{selected?<View key={JSON.stringify([scope,selected.id])} style={{gap:space[2]}}><Text accessibilityRole="header" {...{className:joinClasses(!unstyled&&'text-text')}}>{selected.label}</Text>
   <Button title={`Reset ${selected.label}`} disabled={locked} unstyled={unstyled} onPress={()=>run({type:'reset',effectId:selected.id})}/>
   {selected.presets.length?<Select label={`Preset for ${selected.label}`} value={selected.presetId??''} options={[{value:'',label:'Custom settings',disabled:true},...selected.presets.map(p=>({value:p.id,label:p.label})),...(selected.presetId&&!selected.presets.some(p=>p.id===selected.presetId)?[{value:selected.presetId,label:`Unavailable: ${selected.presetId}`,disabled:true}]:[])]} disabled={locked} unstyled={unstyled} onValueChange={presetId=>run({type:'preset',effectId:selected.id,presetId})}/>:<Text {...{className:joinClasses(!unstyled&&'text-text-muted')}}>No presets supplied for this effect</Text>}
   {selected.parameters.map(p=><View key={p.id}>{p.kind==='number'?<UnitInput scope={JSON.stringify([scope,revision,selected.id,p.id])} label={p.unit?`${p.label} (${p.unit})`:p.label} value={p.value} min={p.minimum} max={p.maximum} step={p.step} disabled={locked} unstyled={unstyled} onCommit={value=>parameter(p.id,value)}/>:p.kind==='boolean'?<SettingSwitch label={p.label} on={p.value} disabled={locked} styled={!unstyled} onChange={value=>parameter(p.id,value)}/>:p.kind==='choice'?<Select label={p.label} value={p.value} options={[...p.choices.map(c=>({value:c.id,label:c.label})),...(!p.choices.some(c=>c.id===p.value)?[{value:p.value,label:`Unavailable: ${p.value}`,disabled:true}]:[])]} disabled={locked} unstyled={unstyled} onValueChange={value=>parameter(p.id,value)}/>:<EffectTextField key={JSON.stringify([scope,revision,selected.id,p.id])} label={p.label} value={p.value} maxLength={p.maxLength} disabled={locked} unstyled={unstyled} onApply={value=>parameter(p.id,value)}/>}</View>)}
  </View>:<Text {...{className:joinClasses(!unstyled&&'text-text-muted')}}>Select an effect to inspect</Text>}</ScrollView>:null}
  {local.section==='library'?<FlatList data={availableEffects} keyExtractor={e=>e.id} style={{height}} initialNumToRender={8} windowSize={5} accessibilityLabel="Available effect types" ListEmptyComponent={<Text {...{className:joinClasses(!unstyled&&'text-text-muted')}}>No effect types supplied</Text>} renderItem={({item})=><Button title={`Add ${item.label}`} disabled={locked||effects.length>=256} unstyled={unstyled} onPress={()=>run({type:'add',typeId:item.id})}/>}/>:null}
  {action.pending!==null?<Button title="Cancel effect request" unstyled={unstyled} onPress={action.cancel}/>:null}<ErrorMessage {...(action.error?{message:action.error}:{})} unstyled={unstyled}/>
 </View>;
}

function EffectTextField({label,value,maxLength,disabled,unstyled,onApply}:{label:string;value:string;maxLength:number;disabled:boolean;unstyled:boolean;onApply:(value:string)=>void}){const id=useId(),[local,store]=useLocalStore(()=>({draft:value}));return <View style={{gap:space[1.5]}}><TextField id={id} label={label} value={local.draft} maxLength={maxLength} editable={!disabled} unstyled={unstyled} onChangeText={draft=>store.set({draft})}/><Button title={`Apply ${label}`} disabled={disabled||local.draft===value} unstyled={unstyled} onPress={()=>{if(!disabled&&local.draft.length<=maxLength)onApply(local.draft);}}/></View>;}

import {createStore} from "zustand/vanilla";

/**
 * A per-instance store for transient gesture and draft state (a drag preview, a
 * text draft, a measured width). Components use it instead of `useState` so a
 * gesture's bookkeeping lives outside React's render cycle and can be read
 * synchronously from responder callbacks. Created by {@linkcode createLocalStore};
 * components use it through `useLocalStore`. Zustand owns the state; this value-replacement
 * adapter remains independent of React.
 */
export interface LocalStore<T> {
  get():T;
  /** Replaces the state, or derives it from the previous state. Listeners run only when it changes. */
  set(next:T|((previous:T)=>T)):void;
  /** Returns the unsubscribe function. */
  subscribe(listener:()=>void):()=>void;
}

/** Creates a {@linkcode LocalStore}. Equal states (by `Object.is`) do not notify. */
export function createLocalStore<T>(initial:T):LocalStore<T>{
  const store=createStore<{value:T}>(()=>({value:initial}));
  return {
    get:()=>store.getState().value,
    set(next){
      store.setState(current=>{
        const value=typeof next==="function"?(next as (p:T)=>T)(current.value):next;
        return Object.is(value,current.value)?current:{value};
      });
    },
    subscribe(listener){return store.subscribe(()=>listener());},
  };
}

import { createStore } from "zustand/vanilla";

/** UI request state. Abort controllers stay in the owner's closure. */
export interface ActionState { readonly pending: string | null; readonly error: string | null }
export function createActionOwner(currentScope: () => string) {
  const store = createStore<ActionState>(() => ({ pending: null, error: null }));
  let active = false;
  let current: { readonly scope: string; readonly abort: AbortController } | null = null;
  function cancel() {
    const previous = current; current = null;
    previous?.abort.abort();
  }
  return {
    store,
    activate() { cancel(); active = true; store.setState({ pending: null, error: null }); },
    deactivate() { active = false; cancel(); },
    cancel() { cancel(); store.setState({ pending: null }); },
    async run<T>(id: string, operation: (signal: AbortSignal) => T | Promise<T>, consume?: (value: T) => void, options?: { pendingForAsyncOnly?: boolean }): Promise<boolean> {
      if (!active) return false;
      cancel();
      const request = { scope: currentScope(), abort: new AbortController() };
      current = request;
      const valid = () => active && current === request && request.scope === currentScope();
      if (options?.pendingForAsyncOnly) store.setState({ error: null });
      else store.setState({ pending: id, error: null });
      try {
        if (!valid()) return false;
        const result = operation(request.abort.signal);
        let value: T;
        if (options?.pendingForAsyncOnly) {
          if (result && typeof (result as Promise<T>).then === 'function') {
            // A synchronous acknowledgement or already-resolved promise must not
            // disable (and blur) the focused control between keyboard commands.
            let settled = false;
            const completion = Promise.resolve(result).then(value => { settled = true; return value; }, error => { settled = true; throw error; });
            void Promise.resolve().then(() => { if (!settled && valid()) store.setState({ pending: id, error: null }); });
            value = await completion;
          } else value = result as T;
        } else value = await result;
        if (!valid()) return false;
        consume?.(value);
        if (!valid()) return false;
        store.setState({ pending: null });
        return true;
      } catch (error) {
        if (!valid()) return false;
        store.setState({ pending: null, error: error instanceof Error ? error.message : String(error) });
        return false;
      } finally { if (current === request) current = null; }
    },
  };
}

import { useLayoutEffect, useRef } from "react";
import { useStore } from "zustand";
import { createActionOwner } from "@/components/nyc-tron/ui/components/shell/action-owner";

/** Cancel stale requests at the committed document boundary, before new controls accept input. */
export function useOwnedAction(scope: string) {
  const committed = useRef(scope);
  const ref = useRef<ReturnType<typeof createActionOwner> | null>(null);
  ref.current ??= createActionOwner(() => committed.current);
  const owner = ref.current;
  useLayoutEffect(() => {
    committed.current = scope;
    owner.activate();
    return () => owner.deactivate();
  }, [owner, scope]);
  const state = useStore(owner.store, value => value);
  const run: typeof owner.run = (id, operation, consume, options) => committed.current === scope ? owner.run(id, operation, consume, options) : Promise.resolve(false);
  return { ...state, run, cancel: owner.cancel };
}

/**
 * Tailwind classes are merged at the APP boundary. Joining without
 * tailwind-merge avoids deleting custom typography/color utilities that
 * depend on each consumer's own @theme configuration.
 */
export function joinClasses(...items: Array<string|false|null|undefined>):string {
  return items.filter(Boolean).join(" ");
}

import {useRef,useSyncExternalStore} from "react";
import {createLocalStore,type LocalStore} from "@/components/nyc-tron/ui/components/local-store";

/**
 * Creates one {@linkcode LocalStore} for the calling component on first render and
 * subscribes to it. Returns the current state and the store.
 */
export function useLocalStore<T>(initial:()=>T):readonly [T,LocalStore<T>]{
  const ref=useRef<LocalStore<T>|null>(null);
  if(!ref.current)ref.current=createLocalStore(initial());
  const store=ref.current;
  const state=useSyncExternalStore(store.subscribe,store.get,store.get);
  return [state,store] as const;
}

